es:@keyframes mesh-float-1 {\n:
@keyframes malla-flotante-1 {
          0%, 100% { transformar: escala(1) traducir3d(0, 0, 0); }
          50% { transformar: escala(1.2) traducir3d(80px, 40px, 0); }
        }
        @keyframes malla-flotante-2 {
          0%, 100% { transformar: escala(1) traducir3d(0, 0, 0); }
          50% { transformar: escala(1.1) traducir3d(-60px, 80px, 0); }
        }
        @keyframes malla-flotante-3 {
          0%, 100% { transformar: escala(1) traducir3d(0, 0, 0); }
          50% { transformar: escala(1.25) traducir3d(40px, -60px, 0); }
        }
        .mesh-gradiente-1 {
          animación: mesh-float-1 20s lineal infinito;
          cambiará: transformará;
        }
        .mesh-gradiente-2 {
          animación: mesh-float-2 25s lineal infinito;
          cambiará: transformará;
        }
        .mesh-gradiente-3 {
          animación: mesh-float-3 18s lineal infinito;
          cambiará: transformará;
        }

es:@keyframes particle-rise {\n:
@keyframes aumento de partículas {
          0% {
            transformar: traducir3d(0, 110vh, 0);
            opacidad: 0;
          }
          10% {
            opacidad: 0,4;
          }
          90% {
            opacidad: 0,4;
          }
          100% {
            transformar: traducir3d(0, -10vh, 0);
            opacidad: 0;
          }
        }
        .bg-partícula {
          animación: ascenso de partículas lineal infinito;
          cambiará: transformará;
        }
